'use strict';

// MODULES //
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var pow = require( '@stdlib/math/base/special/pow' );
var absf = require( '@stdlib/math/base/special/absf' );
var ceilf = require( '@stdlib/math/base/special/ceilf' );
var MAX_SAFE_INTEGER = require( '@stdlib/constants/float32/max-safe-integer' );
var MAX_EXP = require( '@stdlib/constants/float32/max-base10-exponent' );
var MIN_EXP = require( '@stdlib/constants/float32/min-base10-exponent' );
var MIN_EXP_SUBNORMAL = require( '@stdlib/constants/float32/min-base10-exponent-subnormal' );
var PINF = require( '@stdlib/constants/float32/pinf' );


// VARIABLES //

var MAX_INT = MAX_SAFE_INTEGER + 1;
var HUGE = 1.0e+308;


// MAIN //

/**
* Rounds a numeric value to the nearest multiple of \\(10^n\\) toward positive infinity.
*
* @param {number} x - input value
* @param {integer} n - integer power of 10
* @returns {number} rounded value
*
* @example
* // Round a value to 2 decimal places:
* var v = ceilnf( 3.141592653589793, -2 );
* // returns 3.15
*
* @example
* // If n = 0, `ceilnf` behaves like `ceilf`:
* var v = ceilnf( 3.141592653589793, 0 );
* // returns 4.0
*
* @example
* // Round a value to the nearest thousand:
* var v = ceilnf( 12368.0, 3 );
* // returns 13000.0
*/
function ceilnf( x, n ) {
	var s;
	var y;
	if (
		isnan( x ) ||
		isnan( n ) ||
		isInfinitef( n )
	) {
		return NaN;
	}
	if (
		// Handle infinities...
		isInfinitef( x ) ||

		// Handle +-0...
		x === 0.0 ||

		// If `n` exceeds the maximum number of feasible decimal places (such as with subnormal numbers), nothing to round...
		n < MIN_EXP_SUBNORMAL ||

		// If `|x|` is large enough, no decimals to round...
		( absf( x ) > MAX_INT && n <= 0 )
	) {
		return x;
	}
	// The maximum absolute double is ~1.8e308. Accordingly, any possible positive finite `x` rounded to the nearest >=10^309 is infinity and any negative finite `x` is zero.
	if ( n > MAX_EXP ) {
		if ( x <= 0.0 ) {
			return -0.0; // preserve the sign (same behavior as ceil)
		}
		return PINF;
	}
	// If we overflow, return `x`, as the number of digits to the right of the decimal is too small (i.e., `x` is too large / lacks sufficient fractional precision) for there to be any effect when rounding...
	if ( n < MIN_EXP ) {
		s = pow( 10.0, -(n + MAX_EXP) );
		y = (x*HUGE) * s; // order of operation matters!
		if ( isInfinitef( y ) ) {
			return x;
		}
		return ( ceilf(y)/HUGE ) / s;
	}
	s = pow( 10.0, -n );
	y = x * s;
	if ( isInfinitef( y ) ) {
		return x;
	}
	return ceilf( y ) / s;
}


// EXPORTS //

module.exports = ceilnf;
